function opening(s:SlideData){const names=s.section===1?['VS Code','Git','GitHub']:['Google Drive','Supabase','Vercel'];return <div className="openinghero"><div className="openingcopy"><h1>{s.section===1?<><span>Phát triển &amp; </span><em>Quản lý mã nguồn</em></>:<><span>Kết nối dữ liệu</span><br/><em>Triển khai website</em></>}</h1>{s.section===1&&<h2 className="openingSubtitle">VS Code · Git · GitHub</h2>}<p>{s.section===1?'Chỉnh sửa cùng AI trong VS Code; Git quản lý phiên bản.':'Lưu dữ liệu với Supabase, quản lý tài liệu trên Google Drive và đưa ứng dụng lên Vercel.'}</p>{s.section===1&&<p className="openingSecondLine">GitHub lưu mã nguồn và giúp nhóm cộng tác.</p>}<div className="openingroles">{(s.section===1?['Chỉnh sửa','Kiểm tra','Quản lý phiên bản']:['Dữ liệu','Tài liệu','Website']).map(t=><span>{t}</span>)}</div></div><div className="openingfield"><div className="openingglow" aria-hidden="true"/><div className="openingring" aria-hidden="true"/><div className="openingring inner" aria-hidden="true"/><svg className="openinglinks" viewBox="0 0 540 585" aria-hidden="true"><path d="M265 125 L110 430 L430 430 Z"/></svg>{names.map((name,i)=><div className={'openingnode '+(names.length===2?'two-':'three-')+i}><span className="iconplate"><img src={assets[name]} alt={name}/></span><strong>{name}</strong></div>)}</div></div>;}
const featureData:Record<string,{name:string;use:string;example:string;verify:string}[]>={
 'VS Code':[
 {name:'Explorer · cây file',use:'Mở thư mục gốc, xem cấu trúc và chọn file cần chỉnh.',example:'Tìm trang chính và thành phần biểu mẫu tạo yêu cầu.',verify:'Thấy toàn bộ dự án và xác định đúng file sẽ sửa.'},
 {name:'Search · tìm kiếm',use:'Tìm nội dung trong nhiều file để xác định nơi dùng một nhãn hoặc hàm.',example:'Tìm chữ “Tạo yêu cầu” rồi đọc từng kết quả trước khi đổi.',verify:'Bản sửa chỉ tác động nơi cần đổi, không thay thế hàng loạt mù quáng.'},
 {name:'Terminal · chạy tác vụ',use:'Chạy tác vụ của dự án ngay trong VS Code và đọc thông báo lỗi.',example:'Đọc package.json, chạy tác vụ phát triển rồi mở localhost.',verify:'Terminal chạy tại đúng thư mục; trình duyệt hiển thị đúng ứng dụng.'},
 {name:'Extensions · tiện ích',use:'Bổ sung hỗ trợ ngôn ngữ, AI hoặc kết nối GitHub theo nhu cầu.',example:'Chọn trợ lý AI phù hợp và kiểm tra quyền truy cập dự án.',verify:'Biết tiện ích do ai phát hành, chức năng nào được thêm và quyền đã cấp.'},
 {name:'Source Control · thay đổi',use:'Đọc khác biệt, chọn phần sửa và ghi Commit; cần Git được cấu hình.',example:'Chỉ chọn file của nút mới và thông báo lưu thành công.',verify:'Không chọn file bí mật; thông điệp Commit mô tả rõ thay đổi.'}],
 'Git':[
 {name:'Commit · ghi phiên bản',use:'Ghi nhận nhóm thay đổi đã chọn thành một phiên bản trên máy.',example:'Chọn phần sửa của biểu mẫu và ghi Commit mô tả mục tiêu.',verify:'Lịch sử có Commit rõ nghĩa; mã chưa lên GitHub cho đến khi Push.'},
 {name:'Branch · nhánh làm việc',use:'Tách hướng phát triển để thực hiện một tính năng riêng.',example:'Tạo nhánh cho bộ lọc yêu cầu từ phiên bản phù hợp.',verify:'Biết nhánh hiện tại trước khi chỉnh sửa và Commit.'},
 {name:'Diff · so sánh thay đổi',use:'Đọc dòng thêm, xóa hoặc sửa giữa các trạng thái và phiên bản.',example:'Đối chiếu trước và sau khi AI sửa nút lưu.',verify:'Hiểu phần thay đổi, không chọn file bí mật hoặc việc không liên quan.'},
 {name:'Merge · tích hợp',use:'Tích hợp thay đổi giữa các nhánh; xử lý xung đột nếu có.',example:'Đọc hai bản sửa cùng một vùng mã rồi chọn kết quả đúng.',verify:'Sau tích hợp, chạy lại ứng dụng và kiểm tra tính năng bị tác động.'}],
 'GitHub':[
 {name:'Repository · kho mã nguồn',use:'Lưu mã và lịch sử từ xa; quản lý quyền của cộng tác viên.',example:'Mở đúng repository, nhánh và README trước khi nhận dự án.',verify:'Người được cấp quyền hiểu cách chạy; kho không chứa khóa bí mật.'},
 {name:'Commits · lịch sử',use:'Xem từng lần ghi nhận, thông điệp và các dòng thay đổi.',example:'Tìm phiên bản đã thêm thông báo lưu để đối chiếu khi có lỗi.',verify:'Giải thích được thay đổi nào đã lên GitHub và thay đổi nào còn trên máy.'},
 {name:'Branches · nhánh',use:'Tách một hướng phát triển để chưa tác động trực tiếp nhánh chính.',example:'Dùng nhánh riêng cho tính năng lọc yêu cầu.',verify:'Xác nhận nhánh hiện tại trước khi sửa, Commit và Push.'},
 {name:'Pull Request · xem xét',use:'Đề nghị xem xét và trao đổi về thay đổi trước khi hợp nhất.',example:'Mô tả tính năng, cách kiểm tra và gửi cho người xem xét.',verify:'Đọc phần khác biệt và phản hồi; chỉ Merge khi đáp ứng quy trình của nhóm.'},
 {name:'Issues · việc cần làm',use:'Theo dõi yêu cầu, lỗi và thảo luận liên quan đến dự án.',example:'Ghi lỗi nút lưu kèm bước tái hiện và kết quả mong đợi.',verify:'Người khác hiểu và tái hiện được vấn đề mà không cần đoán.'}]
};
function features(){
 const host=h('div',null),tabs=h('div',{className:'featuretabs'}),list=h('div',{className:'featurelist'}),detail=h('div',{className:'featuredetail','aria-live':'polite'});
 let tool='VS Code',selected=0;const tabButtons:Record<string,any>={};let featureButtons:any[]=[];
 function showDetail(){const f=featureData[tool][selected];detail.replaceChildren(<h3>{f.name}</h3>,<div className="featurefacts"><div className="featurefact"><b>Chức năng:</b><p>{f.use}</p></div><div className="featurefact"><b>Ví dụ:</b><p>{f.example}</p></div><div className="featurefact"><b>Kết quả cần thấy:</b><p>{f.verify}</p></div></div>);featureButtons.forEach((button,i)=>{button.className='btn '+(selected===i?'active':'');button.setAttribute('aria-pressed',String(selected===i));});}
 function showTool(){Object.keys(tabButtons).forEach(name=>{tabButtons[name].className='btn '+(tool===name?'active':'');tabButtons[name].setAttribute('aria-pressed',String(tool===name));});featureButtons=featureData[tool].map((f,i)=>btn(f.name,()=>{if(selected===i)return;selected=i;showDetail();}));list.replaceChildren(...featureButtons);showDetail();}
 Object.keys(featureData).forEach(name=>{tabButtons[name]=<button className="btn" onClick={()=>{if(tool===name)return;tool=name;selected=0;showTool();}}><img src={assets[name]} alt=""/>{name}</button>;tabs.append(tabButtons[name]);});
 host.append(tabs,<div className="featuregrid">{list}{detail}</div>);showTool();return host;
}

function outcomeIcon(i:number){return <svg viewBox="0 0 32 32" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{i===0?<><path d="M4 8h9l3 4h12v14H4Z"/><path d="M4 8V5h10l3 3h11v4"/></>:i===1?<><rect x="4" y="4" width="24" height="24" rx="3"/><path d="M11 12l-4 4 4 4m10-8 4 4-4 4m-3-10-4 12"/></>:i===2?<><circle cx="9" cy="7" r="3"/><circle cx="9" cy="25" r="3"/><circle cx="24" cy="8" r="3"/><path d="M9 10v12m15-11v3c0 6-15 2-15 8"/></>:<><circle cx="8" cy="7" r="3"/><circle cx="8" cy="25" r="3"/><circle cx="24" cy="25" r="3"/><path d="M8 10v12m16 0V12c0-5-9-4-9-4m3-3-3 3 3 3"/></>}</svg>;}
